var WorkspaceAllowedFields = map[string]bool{
	"id":       true,
	"name":     true,
	"_version": true,
}

// Quoted field names for Workspace (for SQL generation)
var WorkspaceQuotedFields = map[string]string{
	"id":       `id`,
	"name":     `"name"`,
	"_version": `_version`,
}

// workspaceSortColumns are the columns of Workspace's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended).
var workspaceSortColumns = map[WorkspaceSortField]struct{ sql, key string }{
	WorkspaceSortById:   {`workspace.id`, `page_key.id`},
	WorkspaceSortByName: {`workspace."name"`, `page_key."name"`},
}

// buildWorkspaceOrderByClause builds an ORDER BY clause for Workspace.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildWorkspaceOrderByClause(orderBy []WorkspaceOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := WorkspaceQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func workspaceUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func workspaceUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

