// FindPage reads a page of the Workspace rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *WorkspaceRepository) FindPage(ctx context.Context, filter *WorkspaceFilter, opts *WorkspacePageOptions) (*WorkspacePage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Workspace rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = WorkspaceSortById
	}
	column, ok := workspaceSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Workspace sorts by id and name, not %q", string(field))
	}
	byKey := field == WorkspaceSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := workspaceFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, WorkspaceAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "workspace")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`workspace.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, workspace.id) %s ((SELECT %s FROM workspace AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, workspace.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM workspace%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &WorkspacePage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = workspacePageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *WorkspaceRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM workspace WHERE workspace.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Workspace row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Workspace row through the behaviors' core (D103),
// in a transaction: each behavior's create initializes the fields it owns,
// and the row is read back. A refusal of the core's is returned as the
// *rules.Refusal it is.
func (r *WorkspaceRepository) CreateOne(ctx context.Context, input *WorkspaceCreate) (*types.Workspace, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Workspace, error) {
		return (&WorkspaceRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// workspaceUniqueKeys are the conflict targets of Workspace's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var workspaceUniqueKeys = map[WorkspaceUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	WorkspaceUniqueById: {`(id)`, `id = EXCLUDED.id`, `SELECT "id", "name", "_version" FROM workspace WHERE (id) IN (%s)`, []string{`id`}},
}

// workspaceKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func workspaceKeyOf(on WorkspaceUniqueKey, row *types.Workspace) (string, bool) {
	switch on {
	case WorkspaceUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *WorkspaceRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

