// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
func (r *WorkspaceRepository) upsertRow(ctx context.Context, input *types.Workspace, on WorkspaceUniqueKey, update *WorkspaceUpdate, onlyIfChanged bool) (*UpsertResult[*types.Workspace], error) {
	key := workspaceUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := workspaceUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: name
	fields = append(fields, `"name"`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Name)

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Name != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"name" = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `workspace."name"`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Name)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO workspace (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "name", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Workspace]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Workspace]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with already held the update's values.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Workspace row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Workspace{input})
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Workspace]{Row: found[0], Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *WorkspaceRepository) upsertBatches(ctx context.Context, inputs []*types.Workspace, on WorkspaceUniqueKey, update WorkspaceFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Workspace], error) {
	key := workspaceUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Name {
		setClauses = append(setClauses, `"name" = EXCLUDED."name"`)
		compareCurrent = append(compareCurrent, `workspace."name"`)
		compareNext = append(compareNext, `EXCLUDED."name"`)
	}

	results := make([]UpsertResult[*types.Workspace], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := workspaceUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: name
			{
				cell := batchInsertCell{column: `"name"`, set: true}
				cell.value = input.Name
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO workspace (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "name", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = workspaceKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Workspace], len(prepared))
		for n, row := range returned {
			text, ok := workspaceKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Workspace wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Workspace]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the Workspace row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Workspace, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Workspace row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Workspace]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *WorkspaceRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Workspace, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Workspace
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *WorkspaceRepository) rowsOfKeys(ctx context.Context, on WorkspaceUniqueKey, keys [][]any, inputs []*types.Workspace) ([]*types.Workspace, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(workspaceUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Workspace{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := workspaceKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Workspace, len(inputs))
	for i, input := range inputs {
		text, _ := workspaceKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Workspace row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple Workspace rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *WorkspaceRepository) CreateMany(ctx context.Context, inputs []*WorkspaceCreate) ([]*types.Workspace, error) {
	if len(inputs) == 0 {
		return []*types.Workspace{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Workspace, error) {
		repo := &WorkspaceRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Workspace, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Workspace row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. The update presents the
// preconditions WithPreconditions names (D104). It returns ErrNotFound when
// no live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *WorkspaceRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *WorkspaceUpdate) (*types.Workspace, error) {
	if update == nil {
		update = &WorkspaceUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Workspace, error) {
		repo := &WorkspaceRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Workspace", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns, Preconditions: behaviorPreconditions(ctx)}); err != nil {
			return nil, behaviorNotFound(err, "Workspace", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Workspace records matching the filter
func (r *WorkspaceRepository) UpdateMany(ctx context.Context, filter *WorkspaceFilter, update *WorkspaceUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Name != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"name" = $%d`, paramNum))
		values = append(values, *update.Name)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE workspace SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Workspace row by ID through the
// behaviors' core (D103), in a transaction. The delete presents the
// preconditions WithPreconditions names (D104). It returns ErrNotFound when
// no live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *WorkspaceRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{Preconditions: behaviorPreconditions(ctx)}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Workspace", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Workspace", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Workspace records matching the filter
func (r *WorkspaceRepository) DeleteMany(ctx context.Context, filter *WorkspaceFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM workspace%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
